import * as React from "react";

export type TvIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function TvIcon({ size = 20, ...props }: TvIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="5.5" width="17" height="12" rx="1.5" /><path d="M9 20.5h6M12 17.5v3" />
    </svg>
  );
}
